solution:
extends Node

const SPRITE_DEFAULTS := {"z_index": 0, "visible": true, "flip_h": false}
const LABEL_DEFAULTS := {"text": "", "visible": true}

func scene_lines(node_name: String, type: String, props: Dictionary, defaults: Dictionary) -> Array:
	var lines := []
	lines.append("[node name=\"%s\" type=\"%s\" parent=\".\"]" % [node_name, type])
	for key in props:
		var value = props[key]
		if value == defaults[key]:
			continue
		if value is String:
			lines.append("%s = \"%s\"" % [key, value])
		else:
			lines.append("%s = %s" % [key, value])
	return lines

func _ready() -> void:
	for line in scene_lines("Coin", "Sprite2D", {"z_index": 3, "visible": true, "flip_h": true}, SPRITE_DEFAULTS):
		print(line)
	for line in scene_lines("Score", "Label", {"text": "Coins: 0", "visible": false}, LABEL_DEFAULTS):
		print(line)

