class MiniNode:
	var name := ""
	var parent: MiniNode = null
	var children: Array = []

	func _init(n: String) -> void:
		name = n

	func add_child(child: MiniNode) -> void:
		children.append(child)
		child.parent = self

	func child_named(n: String) -> MiniNode:
		for child in children:
			if child.name == n:
				return child
		return null

	func get_node_or_null(path: String) -> MiniNode:
		var here: MiniNode = self
		for part in path.split("/"):
			if part == "..":
				here = here.parent
			else:
				here = here.child_named(part)
			if here == null:
				return null
		return here

