class MiniNode:
	var name := ""
	var parent: MiniNode = null
	var children: Array = []

	func _init(n: String) -> void:
		name = n

	func add_child(child: MiniNode) -> void:
		children.append(child)
		child.parent = self

	func remove_child(child: MiniNode) -> void:
		if child.parent != self:
			return
		children.erase(child)
		child.parent = null

	func reparent(new_parent: MiniNode) -> void:
		if parent != null:
			parent.remove_child(self)
		new_parent.add_child(self)

