var main := MiniNode.new("Main")
var room := MiniNode.new("Room")
var bed := MiniNode.new("Bed")
var lamp := MiniNode.new("Lamp")
var player := MiniNode.new("Player")
var sprite := MiniNode.new("Sprite")
var hud := MiniNode.new("HUD")
var day_label := MiniNode.new("DayLabel")

func _ready() -> void:
	main.add_child(room)
	room.add_child(bed)
	room.add_child(lamp)
	main.add_child(player)
	player.add_child(sprite)
	main.add_child(hud)
	hud.add_child(day_label)

	lamp.queue_free()
	player.queue_free()
	sprite.queue_free()
	print("Queued three. Nodes in the tree: ", main.count())

# Remove every queued node under main, with its branch.
# Return how many nodes were removed.
func end_of_frame() -> int:
	return sweep(main)

func sweep(node: MiniNode) -> int:
	var freed := 0
	for child in node.children.duplicate():
		if child.queued:
			node.children.erase(child)
			child.parent = null
			freed += child.count()
		else:
			freed += sweep(child)
	return freed

