const RECIPES := {
	"Pancakes":     ["carrot"],
	"Tomato Soup":  ["tomato"],
	"Berry Tart":   ["strawberry"],
	"Roast Dinner": ["carrot", "tomato"],
	"Harvest Pie":  ["pumpkin"],
	"Sunny Salad":  ["sunflower", "tomato"],
}

var crops := {"carrot": 2, "tomato": 1}
var dishes := {}

func can_cook(dish: String) -> bool:
	if not RECIPES.has(dish):
		return false
	for crop in RECIPES[dish]:
		if int(crops.get(crop, 0)) <= 0:
			return false
	return true

func cookable() -> Array:
	var names := []
	for dish in RECIPES:
		if can_cook(dish):
			names.append(dish)
	return names

func cook(dish: String) -> bool:
	if not can_cook(dish):
		return false
	for crop in RECIPES[dish]:
		crops[crop] = int(crops[crop]) - 1
		if crops[crop] <= 0:
			crops.erase(crop)
	dishes[dish] = int(dishes.get(dish, 0)) + 1
	return true

