class Clock:
	const DAY_LENGTH := 480.0

	static func fraction(t: float) -> float:
		return clampf(t / DAY_LENGTH, 0.0, 1.0)

	static func phase(t: float) -> String:
		var f := fraction(t)
		if f < 0.2:
			return "Morning"
		if f < 0.55:
			return "Daytime"
		if f < 0.75:
			return "Evening"
		return "Night"

