var input_map := {
	"move_left": ["A", "Left"],
	"move_right": ["D", "Right"],
	"jump": ["Space"],
	"interact": ["E"],
}

func action_using(key: String) -> String:
	for action in input_map:
		if key in input_map[action]:
			return action
	return ""

func rebind(action: String, old_key: String, new_key: String) -> bool:
	if not input_map.has(action):
		return false
	var keys: Array = input_map[action]
	var at := keys.find(old_key)
	if at == -1:
		return false
	if action_using(new_key) != "":
		return false
	keys[at] = new_key
	return true

