func camera_centre(target: Vector2, view: Vector2, room: Vector2) -> Vector2:
	var half := view / 2
	var out := target
	if room.x <= view.x:
		out.x = room.x / 2
	else:
		out.x = clampf(target.x, half.x, room.x - half.x)
	if room.y <= view.y:
		out.y = room.y / 2
	else:
		out.y = clampf(target.y, half.y, room.y - half.y)
	return out

func _ready() -> void:
	print(camera_centre(Vector2(10, 10), Vector2(320, 180), Vector2(640, 360)))

