	return p.distance_to(nearest)

func blocked(p: Vector2) -> bool:
	if not FLOOR.has_point(p):
		return true
	for r in solids:
		if to_box(p, r) < RADIUS:
			return true
	return false

func _process(delta: float) -> void:
	var want := Input.get_vector("ui_left", "ui_right", "ui_up", "ui_down") * SPEED
	vel = vel.move_toward(want, ACCEL * delta)
	var step := vel * delta
	if blocked(Vector2(pos.x + step.x, pos.y)):
