func chain_at(start: float, steps: Array, t: float) -> float:
	var from := start
	for step in steps:
		var to: float = step[0]
		var duration: float = step[1]
		if t < duration:
			return lerpf(from, to, t / duration)
		t -= duration
		from = to
	return from

