const MIN_VIEW := Vector2i(940, 520)

func fit(screen: Vector2i) -> Dictionary:
	var n := maxi(1, mini(screen.x / MIN_VIEW.x, screen.y / MIN_VIEW.y))
	return {"scale": n, "view": Vector2i(screen.x / n, screen.y / n)}

func lost(screen: Vector2i) -> Vector2i:
	var f := fit(screen)
	var view: Vector2i = f["view"]
	var n: int = f["scale"]
	return screen - view * n

