const HEADER := "LH-1"

func make_code(data: Dictionary) -> String:
	var json := JSON.stringify(data)
	return "%s:%d:%s" % [HEADER, json.length(), json]

func read_code(text: String) -> Dictionary:
	var clean := text.strip_edges()
	if not clean.begins_with(HEADER + ":"):
		return {}
	var rest := clean.substr(HEADER.length() + 1)
	var colon := rest.find(":")
	if colon < 0:
		return {}
	var want := int(rest.substr(0, colon))
	var json := rest.substr(colon + 1)
	if json.length() != want:
		return {}
	var parsed: Variant = JSON.parse_string(json)
	if typeof(parsed) != TYPE_DICTIONARY:
		return {}
	return parsed

