var heard: Array = []
var _undoing := false

func change(key: String, value) -> void:
	var old = state.get(key)
	if old == value:
		return
	if not _undoing:
		history.append([key, old])
	state[key] = value
	state_changed.emit(key, value)

func undo() -> void:
	if history.is_empty():
		return
	var last: Array = history.pop_back()
	_undoing = true
	change(last[0], last[1])
	_undoing = false

