const GROW := 15.0        # seconds a crop needs in the ground

# Seconds into TODAY. It starts again from 0 every morning.
var clock_t := 0.0
var plot := {"planted_at": 0.0, "ready": false}

func plant() -> void:
	plot = {"planted_at": clock_t, "ready": false}

func sleep() -> void:
	clock_t = 0.0

func tick() -> void:
	if plot["planted_at"] > clock_t:
		plot["planted_at"] = 0.0
	if clock_t - plot["planted_at"] >= GROW:
		plot["ready"] = true

# Plant at one time, perhaps sleep, look at another. Is the crop ready?
func scenario(plant_at: float, sleeps: bool, look_at: float) -> bool:
	clock_t = plant_at
	plant()
	if sleeps:
		sleep()
	clock_t = look_at
	tick()
	return plot["ready"]

func _ready() -> void:
	print("Same day, 15 s later:    ", scenario(100.0, false, 115.0))
	print("Evening, then 20 s in:   ", scenario(450.0, true, 20.0))

