const USED := ["bed.png", "lamp.png", "bed.png", "rug.png", "vase.png"]
const FILES := ["lamp.png", "bed.png", "sofa.png", "old_bed.png"]

func audit(used: Array, files: Array) -> Dictionary:
	var missing := []
	var unused := []
	var twice := []
	for file in used:
		if not files.has(file) and not missing.has(file):
			missing.append(file)
		if used.count(file) > 1 and not twice.has(file):
			twice.append(file)
	for file in files:
		if not used.has(file) and not unused.has(file):
			unused.append(file)
	missing.sort()
	unused.sort()
	twice.sort()
	return {"missing": missing, "unused": unused, "twice": twice}

func _ready() -> void:
	print(audit(USED, FILES))

